         WHEN lower(trim(`sox_compliant_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sox_compliant_flag`,
    CASE WHEN lower(trim(`supports_cost_of_sales_accounting`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`supports_cost_of_sales_accounting`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `supports_cost_of_sales_accounting`,
    CASE WHEN lower(trim(`supports_profit_center_accounting`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`supports_profit_center_accounting`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `supports_profit_center_accounting`,
    CASE WHEN lower(trim(`supports_segment_reporting`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`supports_segment_reporting`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `supports_segment_reporting`,
    CASE lower(trim(`valuation_view`))
      WHEN 'legal' THEN 'legal'
      WHEN 'group' THEN 'group'
      WHEN 'profit_center' THEN 'profit_center'
      WHEN 'cost_center' THEN 'cost_center'
      ELSE NULLIF(trim(`valuation_view`), '')
    END AS `valuation_view`,
    NULLIF(trim(`created_by`), '') AS `created_by`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_ledger
)
SELECT *
FROM typed
QUALIFY `ledger_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `ledger_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- finance.journal_entry ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.finance_journal_entry (
  CONSTRAINT `journal_entry_id_not_null` EXPECT (`journal_entry_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: finance.journal_entry typed and cleaned, one row per journal_entry_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`journal_entry_id`), '') AS BIGINT) AS `journal_entry_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`ledger_id`), '') AS BIGINT) AS `ledger_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    COALESCE(try_to_timestamp(trim(`approval_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approval_timestamp`) AS TIMESTAMP)) AS `approval_timestamp`,
    COALESCE(try_to_date(trim(`baseline_payment_date`), 'yyyy-MM-dd'), try_to_date(trim(`baseline_payment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`baseline_payment_date`) AS DATE)) AS `baseline_payment_date`,
    NULLIF(trim(`batch_input_session`), '') AS `batch_input_session`,
    NULLIF(trim(`business_area_code`), '') AS `business_area_code`,
    COALESCE(try_to_date(trim(`clearing_date`), 'yyyy-MM-dd'), try_to_date(trim(`clearing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`clearing_date`) AS DATE)) AS `clearing_date`,
    NULLIF(trim(`clearing_document_number`), '') AS `clearing_document_number`,
    NULLIF(trim(`controlling_area`), '') AS `controlling_area`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`document_date`), 'yyyy-MM-dd'), try_to_date(trim(`document_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`document_date`) AS DATE)) AS `document_date`,
    NULLIF(trim(`document_number`), '') AS `document_number`,
    NULLIF(trim(`document_type`), '') AS `document_type`,
    COALESCE(try_to_date(trim(`entry_date`), 'yyyy-MM-dd'), try_to_date(trim(`entry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`entry_date`) AS DATE)) AS `entry_date`,
    TRY_CAST(NULLIF(trim(`exchange_rate`), '') AS DECIMAL(15,5)) AS `exchange_rate`,
    CASE lower(trim(`exchange_rate_type`))
      WHEN 'm' THEN 'M'
      WHEN 'b' THEN 'B'
      WHEN 'g' THEN 'G'
      WHEN 'p' THEN 'P'
      ELSE NULLIF(trim(`exchange_rate_type`), '')
    END AS `exchange_rate_type`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    NULLIF(trim(`functional_area_code`), '') AS `functional_area_code`,
    NULLIF(trim(`header_text`), '') AS `header_text`,
    CASE WHEN lower(trim(`intercompany_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`intercompany_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `intercompany_indicator`,
    NULLIF(trim(`ledger_group`), '') AS `ledger_group`,
    NULLIF(trim(`local_currency_code`), '') AS `local_currency_code`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`payment_terms_code`), '') AS `payment_terms_code`,
    COALESCE(try_to_date(trim(`posting_date`), 'yyyy-MM-dd'), try_to_date(trim(`posting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`posting_date`) AS DATE)) AS `posting_date`,
    CASE lower(trim(`posting_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'posted' THEN 'posted'
      WHEN 'parked' THEN 'parked'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'reversed' THEN 'reversed'
      ELSE NULLIF(trim(`posting_status`), '')
    END AS `posting_status`,
    NULLIF(trim(`reference_document_number`), '') AS `reference_document_number`,
    CASE WHEN lower(trim(`reversal_indicator`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`reversal_indicator`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `reversal_indicator`,
    CASE lower(trim(`reversal_reason_code`))
      WHEN '01' THEN '01'
      WHEN '02' THEN '02'
      WHEN '03' THEN '03'
      WHEN '04' THEN '04'
      WHEN '05' THEN '05'
      WHEN '06' THEN '06'
      ELSE NULLIF(trim(`reversal_reason_code`), '')
    END AS `reversal_reason_code`,
    NULLIF(trim(`reversed_document_number`), '') AS `reversed_document_number`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    CASE WHEN lower(trim(`sox_control_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sox_control_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sox_control_flag`,
    COALESCE(try_to_date(trim(`tax_reporting_date`), 'yyyy-MM-dd'), try_to_date(trim(`tax_reporting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`tax_reporting_date`) AS DATE)) AS `tax_reporting_date`,
    NULLIF(trim(`trading_partner_company_code`), '') AS `trading_partner_company_code`,
    NULLIF(trim(`transaction_code`), '') AS `transaction_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_journal_entry
)
SELECT *
FROM typed
QUALIFY `journal_entry_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `journal_entry_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

