-- finance.ar_invoice ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.finance_ar_invoice (
  CONSTRAINT `ar_invoice_id_not_null` EXPECT (`ar_invoice_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `gross_amount_not_negative` EXPECT (`gross_amount` IS NULL OR `gross_amount` >= 0),
  CONSTRAINT `net_amount_not_negative` EXPECT (`net_amount` IS NULL OR `net_amount` >= 0),
  CONSTRAINT `tax_amount_not_negative` EXPECT (`tax_amount` IS NULL OR `tax_amount` >= 0),
  CONSTRAINT `total_amount_not_negative` EXPECT (`total_amount` IS NULL OR `total_amount` >= 0),
  CONSTRAINT `amount_received_not_negative` EXPECT (`amount_received` IS NULL OR `amount_received` >= 0)
)
COMMENT 'Silver: finance.ar_invoice typed and cleaned, one row per ar_invoice_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`ar_invoice_id`), '') AS BIGINT) AS `ar_invoice_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`sales_invoice_id`), '') AS BIGINT) AS `sales_invoice_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`amount_received`), '') AS DECIMAL(18,2)) AS `amount_received`,
    COALESCE(try_to_date(trim(`billing_date`), 'yyyy-MM-dd'), try_to_date(trim(`billing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`billing_date`) AS DATE)) AS `billing_date`,
    NULLIF(trim(`billing_document_type`), '') AS `billing_document_type`,
    COALESCE(try_to_date(trim(`clearing_date`), 'yyyy-MM-dd'), try_to_date(trim(`clearing_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`clearing_date`) AS DATE)) AS `clearing_date`,
    NULLIF(trim(`clearing_reference`), '') AS `clearing_reference`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`deduction_amount`), '') AS DECIMAL(18,2)) AS `deduction_amount`,
    NULLIF(trim(`deduction_reason_code`), '') AS `deduction_reason_code`,
    CASE WHEN lower(trim(`dispute_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dispute_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dispute_flag`,
    NULLIF(trim(`dispute_reason`), '') AS `dispute_reason`,
    NULLIF(trim(`distribution_channel`), '') AS `distribution_channel`,
    CASE lower(trim(`dso_aging_bucket`))
      WHEN 'current' THEN 'current'
      WHEN '1_30_days' THEN '1_30_days'
      WHEN '31_60_days' THEN '31_60_days'
      WHEN '61_90_days' THEN '61_90_days'
      WHEN 'over_90_days' THEN 'over_90_days'
      WHEN 'over_120_days' THEN 'over_120_days'
      ELSE NULLIF(trim(`dso_aging_bucket`), '')
    END AS `dso_aging_bucket`,
    COALESCE(try_to_date(trim(`due_date`), 'yyyy-MM-dd'), try_to_date(trim(`due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`due_date`) AS DATE)) AS `due_date`,
    TRY_CAST(NULLIF(trim(`dunning_level`), '') AS INT) AS `dunning_level`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    COALESCE(try_to_date(trim(`gl_posting_date`), 'yyyy-MM-dd'), try_to_date(trim(`gl_posting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`gl_posting_date`) AS DATE)) AS `gl_posting_date`,
    TRY_CAST(NULLIF(trim(`gross_amount`), '') AS DECIMAL(18,2)) AS `gross_amount`,
    NULLIF(trim(`invoice_number`), '') AS `invoice_number`,
    NULLIF(trim(`invoice_status`), '') AS `invoice_status`,
    COALESCE(try_to_date(trim(`last_dunning_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_dunning_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_dunning_date`) AS DATE)) AS `last_dunning_date`,
    NULLIF(trim(`modified_by_user`), '') AS `modified_by_user`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    TRY_CAST(NULLIF(trim(`net_amount`), '') AS DECIMAL(18,2)) AS `net_amount`,
    TRY_CAST(NULLIF(trim(`outstanding_balance`), '') AS DECIMAL(18,2)) AS `outstanding_balance`,
    COALESCE(try_to_date(trim(`payment_date`), 'yyyy-MM-dd'), try_to_date(trim(`payment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`payment_date`) AS DATE)) AS `payment_date`,
    CASE lower(trim(`payment_method`))
      WHEN 'wire_transfer' THEN 'wire_transfer'
      WHEN 'ach' THEN 'ach'
      WHEN 'check' THEN 'check'
      WHEN 'credit_card' THEN 'credit_card'
      WHEN 'edi_payment' THEN 'edi_payment'
      WHEN 'direct_debit' THEN 'direct_debit'
      ELSE NULLIF(trim(`payment_method`), '')
    END AS `payment_method`,
    NULLIF(trim(`payment_terms_code`), '') AS `payment_terms_code`,
    COALESCE(try_to_date(trim(`revenue_recognition_date`), 'yyyy-MM-dd'), try_to_date(trim(`revenue_recognition_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`revenue_recognition_date`) AS DATE)) AS `revenue_recognition_date`,
    NULLIF(trim(`sales_order_number`), '') AS `sales_order_number`,
    NULLIF(trim(`sales_organization`), '') AS `sales_organization`,
    NULLIF(trim(`shipment_number`), '') AS `shipment_number`,
    TRY_CAST(NULLIF(trim(`tax_amount`), '') AS DECIMAL(18,2)) AS `tax_amount`,
    TRY_CAST(NULLIF(trim(`total_amount`), '') AS DECIMAL(18,2)) AS `total_amount`,
    TRY_CAST(NULLIF(trim(`trade_discount_amount`), '') AS DECIMAL(18,2)) AS `trade_discount_amount`,
    TRY_CAST(NULLIF(trim(`write_off_amount`), '') AS DECIMAL(18,2)) AS `write_off_amount`,
    COALESCE(try_to_date(trim(`write_off_date`), 'yyyy-MM-dd'), try_to_date(trim(`write_off_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`write_off_date`) AS DATE)) AS `write_off_date`,
    NULLIF(trim(`write_off_reason_code`), '') AS `write_off_reason_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_ar_invoice
)
SELECT *
FROM typed
QUALIFY `ar_invoice_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `ar_invoice_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- finance.ar_payment ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.finance_ar_payment (
  CONSTRAINT `ar_payment_id_not_null` EXPECT (`ar_payment_id` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `payment_amount_not_negative` EXPECT (`payment_amount` IS NULL OR `payment_amount` >= 0),
  CONSTRAINT `applied_amount_not_negative` EXPECT (`applied_amount` IS NULL OR `applied_amount` >= 0)
)
COMMENT 'Silver: finance.ar_payment typed and cleaned, one row per ar_payment_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`ar_payment_id`), '') AS BIGINT) AS `ar_payment_id`,
    TRY_CAST(NULLIF(trim(`ar_invoice_id`), '') AS BIGINT) AS `ar_invoice_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`invoice_id`), '') AS BIGINT) AS `invoice_id`,
    TRY_CAST(NULLIF(trim(`shopper_id`), '') AS BIGINT) AS `shopper_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`applied_amount`), '') AS DECIMAL(18,2)) AS `applied_amount`,
    TRY_CAST(NULLIF(trim(`bank_account_code`), '') AS BIGINT) AS `bank_account_code`,
    NULLIF(trim(`bank_reference_number`), '') AS `bank_reference_number`,
    NULLIF(trim(`business_area_code`), '') AS `business_area_code`,
    NULLIF(trim(`check_number`), '') AS `check_number`,
    NULLIF(trim(`clearing_document_number`), '') AS `clearing_document_number`,
    NULLIF(trim(`company_code`), '') AS `company_code`,
    NULLIF(trim(`created_by_user`), '') AS `created_by_user`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    TRY_CAST(NULLIF(trim(`days_to_pay`), '') AS INT) AS `days_to_pay`,
    TRY_CAST(NULLIF(trim(`deduction_amount`), '') AS DECIMAL(18,2)) AS `deduction_amount`,
    NULLIF(trim(`deduction_notes`), '') AS `deduction_notes`,
    NULLIF(trim(`deduction_reason_code`), '') AS `deduction_reason_code`,
    TRY_CAST(NULLIF(trim(`discount_amount`), '') AS DECIMAL(18,2)) AS `discount_amount`,
    COALESCE(try_to_date(trim(`due_date`), 'yyyy-MM-dd'), try_to_date(trim(`due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`due_date`) AS DATE)) AS `due_date`,
    NULLIF(trim(`edi_transaction_set_reference`), '') AS `edi_transaction_set_reference`,
    TRY_CAST(NULLIF(trim(`exchange_rate`), '') AS DECIMAL(12,6)) AS `exchange_rate`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    TRY_CAST(NULLIF(trim(`local_currency_amount`), '') AS DECIMAL(18,2)) AS `local_currency_amount`,
    NULLIF(trim(`local_currency_code`), '') AS `local_currency_code`,
    NULLIF(trim(`lockbox_batch_number`), '') AS `lockbox_batch_number`,
    NULLIF(trim(`modified_by_user`), '') AS `modified_by_user`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    CASE WHEN lower(trim(`overpayment_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`overpayment_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `overpayment_flag`,
    CASE WHEN lower(trim(`partial_payment_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`partial_payment_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `partial_payment_flag`,
    TRY_CAST(NULLIF(trim(`payment_amount`), '') AS DECIMAL(18,2)) AS `payment_amount`,
    CASE lower(trim(`payment_channel`))
      WHEN 'online_portal' THEN 'online_portal'
      WHEN 'mobile_app' THEN 'mobile_app'
      WHEN 'edi_820' THEN 'edi_820'
      WHEN 'bank_transfer' THEN 'bank_transfer'
      WHEN 'lockbox' THEN 'lockbox'
      WHEN 'manual_entry' THEN 'manual_entry'
      ELSE NULLIF(trim(`payment_channel`), '')
    END AS `payment_channel`,
    NULLIF(trim(`payment_currency_code`), '') AS `payment_currency_code`,
    COALESCE(try_to_date(trim(`payment_date`), 'yyyy-MM-dd'), try_to_date(trim(`payment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`payment_date`) AS DATE)) AS `payment_date`,
    NULLIF(trim(`payment_document_number`), '') AS `payment_document_number`,
    CASE lower(trim(`payment_method`))
      WHEN 'ach' THEN 'ACH'
      WHEN 'wire_transfer' THEN 'wire_transfer'
      WHEN 'check' THEN 'check'
      WHEN 'credit_card' THEN 'credit_card'
      WHEN 'debit_card' THEN 'debit_card'
      WHEN 'electronic_funds_transfer' THEN 'electronic_funds_transfer'
      ELSE NULLIF(trim(`payment_method`), '')
    END AS `payment_method`,
    NULLIF(trim(`payment_processor_code`), '') AS `payment_processor_code`,
    NULLIF(trim(`payment_status`), '') AS `payment_status`,
    NULLIF(trim(`payment_terms_code`), '') AS `payment_terms_code`,
    COALESCE(try_to_date(trim(`posting_date`), 'yyyy-MM-dd'), try_to_date(trim(`posting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`posting_date`) AS DATE)) AS `posting_date`,
    NULLIF(trim(`remittance_advice_number`), '') AS `remittance_advice_number`,
    COALESCE(try_to_date(trim(`reversal_date`), 'yyyy-MM-dd'), try_to_date(trim(`reversal_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`reversal_date`) AS DATE)) AS `reversal_date`,
    CASE WHEN lower(trim(`reversal_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`reversal_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `reversal_flag`,
    NULLIF(trim(`reversal_reason_code`), '') AS `reversal_reason_code`,
    CASE WHEN lower(trim(`short_payment_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`short_payment_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `short_payment_flag`,
    COALESCE(try_to_date(trim(`value_date`), 'yyyy-MM-dd'), try_to_date(trim(`value_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`value_date`) AS DATE)) AS `value_date`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_ar_payment
)
SELECT *
FROM typed
QUALIFY `ar_payment_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `ar_payment_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

