      WHEN 'standard' THEN 'standard'
      WHEN 'actual' THEN 'actual'
      WHEN 'planned' THEN 'planned'
      WHEN 'simulated' THEN 'simulated'
      ELSE NULLIF(trim(`costing_type`), '')
    END AS `costing_type`,
    NULLIF(trim(`costing_version`), '') AS `costing_version`,
