    NULLIF(trim(`lot_size_unit`), '') AS `lot_size_unit`,
    TRY_CAST(NULLIF(trim(`machine_overhead_cost`), '') AS DECIMAL(18,2)) AS `machine_overhead_cost`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`packaging_cost`), '') AS DECIMAL(18,2)) AS `packaging_cost`,
    CASE lower(trim(`price_control_indicator`))
      WHEN 's' THEN 'S'
      WHEN 'v' THEN 'V'
      ELSE NULLIF(trim(`price_control_indicator`), '')
    END AS `price_control_indicator`,
    TRY_CAST(NULLIF(trim(`raw_material_cost`), '') AS DECIMAL(18,2)) AS `raw_material_cost`,
    CASE lower(trim(`release_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'released' THEN 'released'
      WHEN 'locked' THEN 'locked'
      WHEN 'archived' THEN 'archived'
      ELSE NULLIF(trim(`release_status`), '')
    END AS `release_status`,
    TRY_CAST(NULLIF(trim(`total_cost_amount`), '') AS DECIMAL(18,2)) AS `total_cost_amount`,
    COALESCE(try_to_date(trim(`validity_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`validity_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`validity_end_date`) AS DATE)) AS `validity_end_date`,
    COALESCE(try_to_date(trim(`validity_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`validity_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`validity_start_date`) AS DATE)) AS `validity_start_date`,
    NULLIF(trim(`valuation_class`), '') AS `valuation_class`,
    TRY_CAST(NULLIF(trim(`variable_overhead_cost`), '') AS DECIMAL(18,2)) AS `variable_overhead_cost`,
    TRY_CAST(NULLIF(trim(`variance_amount`), '') AS DECIMAL(18,2)) AS `variance_amount`,
    CASE lower(trim(`variance_category`))
      WHEN 'price' THEN 'price'
      WHEN 'quantity' THEN 'quantity'
      WHEN 'mix' THEN 'mix'
      WHEN 'yield' THEN 'yield'
      WHEN 'efficiency' THEN 'efficiency'
      WHEN 'volume' THEN 'volume'
      ELSE NULLIF(trim(`variance_category`), '')
    END AS `variance_category`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_cogs_allocation
)
SELECT *
FROM typed
QUALIFY `cogs_allocation_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `cogs_allocation_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

