    TRY_CAST(NULLIF(trim(`fixed_overhead_cost`), '') AS DECIMAL(18,4)) AS `fixed_overhead_cost`,
    TRY_CAST(NULLIF(trim(`freight_in_cost`), '') AS DECIMAL(18,4)) AS `freight_in_cost`,
    TRY_CAST(NULLIF(trim(`machine_overhead_cost`), '') AS DECIMAL(18,4)) AS `machine_overhead_cost`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`packaging_material_cost`), '') AS DECIMAL(18,4)) AS `packaging_material_cost`,
    TRY_CAST(NULLIF(trim(`previous_standard_cost`), '') AS DECIMAL(18,4)) AS `previous_standard_cost`,
    TRY_CAST(NULLIF(trim(`raw_material_cost`), '') AS DECIMAL(18,4)) AS `raw_material_cost`,
    COALESCE(try_to_date(trim(`release_date`), 'yyyy-MM-dd'), try_to_date(trim(`release_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`release_date`) AS DATE)) AS `release_date`,
    CASE lower(trim(`release_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'released' THEN 'released'
      WHEN 'locked' THEN 'locked'
      WHEN 'archived' THEN 'archived'
      ELSE NULLIF(trim(`release_status`), '')
    END AS `release_status`,
    NULLIF(trim(`routing_usage`), '') AS `routing_usage`,
    TRY_CAST(NULLIF(trim(`total_standard_cost`), '') AS DECIMAL(18,4)) AS `total_standard_cost`,
    COALESCE(try_to_date(trim(`valid_from_date`), 'yyyy-MM-dd'), try_to_date(trim(`valid_from_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`valid_from_date`) AS DATE)) AS `valid_from_date`,
    COALESCE(try_to_date(trim(`valid_to_date`), 'yyyy-MM-dd'), try_to_date(trim(`valid_to_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`valid_to_date`) AS DATE)) AS `valid_to_date`,
    NULLIF(trim(`valuation_variant`), '') AS `valuation_variant`,
    TRY_CAST(NULLIF(trim(`variable_overhead_cost`), '') AS DECIMAL(18,4)) AS `variable_overhead_cost`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_standard_cost
)
SELECT *
FROM typed
QUALIFY `standard_cost_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `standard_cost_id` ORDER BY `cost_estimate_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- finance.company_code ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.finance_company_code (
  CONSTRAINT `company_code_id_not_null` EXPECT (`company_code_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: finance.company_code typed and cleaned, one row per company_code_id (latest record_audit_updated wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`parent_company_code_id`), '') AS BIGINT) AS `parent_company_code_id`,
    NULLIF(trim(`address_line1`), '') AS `address_line1`,
    NULLIF(trim(`address_line2`), '') AS `address_line2`,
    NULLIF(trim(`city`), '') AS `city`,
    NULLIF(trim(`classification_type`), '') AS `classification_type`,
    NULLIF(trim(`code`), '') AS `code`,
    NULLIF(trim(`cost_center_code`), '') AS `cost_center_code`,
    NULLIF(trim(`country_code`), '') AS `country_code`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`effective_from`), 'yyyy-MM-dd'), try_to_date(trim(`effective_from`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_from`) AS DATE)) AS `effective_from`,
    COALESCE(try_to_date(trim(`effective_to`), 'yyyy-MM-dd'), try_to_date(trim(`effective_to`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_to`) AS DATE)) AS `effective_to`,
    NULLIF(trim(`email_address`), '') AS `email_address`,
    NULLIF(trim(`industry_code`), '') AS `industry_code`,
    CASE WHEN lower(trim(`is_consolidated_entity`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_consolidated_entity`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_consolidated_entity`,
    CASE WHEN lower(trim(`is_public_company`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_public_company`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_public_company`,
    NULLIF(trim(`legal_name`), '') AS `legal_name`,
    NULLIF(trim(`lifecycle_status`), '') AS `lifecycle_status`,
    NULLIF(trim(`name`), '') AS `name`,
    NULLIF(trim(`parent_company_code`), '') AS `parent_company_code`,
    NULLIF(trim(`phone_number`), '') AS `phone_number`,
    NULLIF(trim(`postal_code`), '') AS `postal_code`,
    NULLIF(trim(`primary_contact_method`), '') AS `primary_contact_method`,
    COALESCE(try_to_timestamp(trim(`record_audit_created`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`record_audit_created`) AS TIMESTAMP)) AS `record_audit_created`,
    COALESCE(try_to_timestamp(trim(`record_audit_updated`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`record_audit_updated`) AS TIMESTAMP)) AS `record_audit_updated`,
    NULLIF(trim(`state_province`), '') AS `state_province`,
    NULLIF(trim(`tax_number`), '') AS `tax_number`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.finance_company_code
)
SELECT *
FROM typed
QUALIFY `company_code_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `company_code_id` ORDER BY `record_audit_updated` DESC NULLS LAST, _ingested_at DESC) = 1;
